 347: // --- Token Estimation (Simple Heuristic) ---
 348: 
 349: function estimateTokens(messages: Message[]): number {
 350:   let total = 0;
 351:   for (const msg of messages) {
 352:     switch (msg.role) {
 353:       case "user":
 354:         for (const block of msg.content) {
 355:           if (block.type === "text") total += block.text.length;
 356:         }
 357:         break;
 358:       case "assistant":
 359:         if (msg.content) total += msg.content.length;
 360:         if (msg.tool_calls) {
 361:           for (const tc of msg.tool_calls) {
 362:             total += tc.function.arguments.length + tc.function.name.length;
 363:           }
 364:         }
 365:         break;
 366:       case "tool":
 367:         total += msg.content.length;
 368:         break;
 369:       case "system":
 370:         total += msg.content.length;
 371:         break;
 372:     }
 373:   }
 374:   // Rough estimate: ~1 token per 4 characters
 375:   return Math.ceil(total / 4);
 376: }
