 378: // --- Auto-Compaction ---
 379: 
 380: /**
 381:  * Choose a split point so the retained tail never begins with an orphan tool
 382:  * result. Starts at `messages.length - tailSize` and walks the boundary
 383:  * earlier while the first tail message is a tool result (whose originating
 384:  * assistant message would otherwise be stranded in the summarized half).
 385:  * Returns an index into `messages` (the start of the tail).
 386:  */
 387: function findSafeSplitIndex(messages: Message[], tailSize: number): number {
 388:   let split = Math.max(0, messages.length - tailSize);
 389:   while (split > 0 && messages[split]?.role === "tool") {
 390:     split--;
 391:   }
 392:   return split;
 393: }
 394: 
 395: export async function autoCompact(
 396:   messages: Message[],
 397:   callModel: ModelCaller,
 398:   modelConfig: ModelConfig,
 399: ): Promise<Message[]> {
 400:   const TAIL_SIZE = 20;
 401:   // Find a safe split point. Slicing at a fixed offset can leave the tail
 402:   // starting with an orphan tool result whose assistant (with tool_calls)
 403:   // landed in oldMessages — the provider rejects that ("tool message must
 404:   // follow tool_calls"). Move the boundary earlier until the tail no longer
 405:   // begins with a tool message.
 406:   const splitIndex = findSafeSplitIndex(messages, TAIL_SIZE);
 407: 
 408:   const oldMessages = messages.slice(0, splitIndex);
 409:   const tailMessages = messages.slice(splitIndex);
 410: 
 411:   if (oldMessages.length === 0) return messages;
 412: 
 413:   // Summarize old messages
 414:   const summaryPrompt = `Summarize the conversation so far. Include:
 415: 1. What the user asked for (the main task)
 416: 2. Key decisions made
 417: 3. Files that were modified (with paths)
 418: 4. What still needs to be done
 419: 5. Any important context for continuing the work
 420: 
 421: Be concise but complete. This summary will replace the old messages
 422: so the conversation can continue with a fresh context window.`;
 423: 
 424:   const summaryMessages: Message[] = [
 425:     ...oldMessages,
 426:     { role: "user", content: [{ type: "text", text: summaryPrompt }] },
 427:   ];
 428: 
 429:   // Call model without tools for summarization
 430:   const chunks: string[] = [];
 431:   for await (const event of callModel(
 432:     summaryMessages,
 433:     [],
 434:     "You are a helpful assistant that summarizes conversations.",
 435:     modelConfig,
 436:   )) {
 437:     if (event.type === "text_delta") {
 438:       chunks.push(event.delta);
 439:     }
 440:   }
 441:   const summary = chunks.join("");
 442: 
 443:   // Rebuild: system summary + tail
 444:   return [
 445:     {
 446:       role: "system",
 447:       content: `[CONVERSATION SUMMARY]\n${summary}`,
 448:     },
 449:     ...tailMessages,
 450:   ];
 451: }
 452: 
 453: // --- Error Recovery ---
 454: 
 455: async function handleModelError(
 456:   error: unknown,
 457:   _messages: Message[],
 458:   _callModel: ModelCaller,
 459:   _modelConfig: ModelConfig,
 460: ): Promise<"retry" | "abort"> {
 461:   const err = error as any;
 462: 
 463:   // Rate limit → wait and retry
 464:   if (err?.status === 429) {
 465:     const delay = err?.retryAfter || 5000;
 466:     await sleep(delay);
 467:     return "retry";
 468:   }
 469: 
 470:   // Context too long → compact and retry
 471:   if (
 472:     err?.status === 400 &&
 473:     (err?.message?.includes("context_length") ||
 474:       err?.message?.includes("maximum context"))
 475:   ) {
 476:     return "retry";
 477:   }
 478: 
 479:   // Auth error → abort
 480:   if (err?.status === 401 || err?.status === 403) {
 481:     return "abort";
 482:   }
 483: 
 484:   // Unknown error → abort
 485:   return "abort";
 486: }
 487: 
 488: function sleep(ms: number): Promise<void> {
 489:   return new Promise((resolve) => setTimeout(resolve, ms));
 490: }
