 309:   // eslint-disable-next-line no-constant-condition
 310:   while (true) {
 311:     const userInput = await readInput();
 312: 
 313:     // null = stdin closed (EOF / Ctrl+D). Exit the REPL cleanly.
 314:     if (userInput === null) break;
 315:     if (!userInput.trim()) continue;
 316:     if (userInput.toLowerCase() === "exit") break;
 317: 
 318:     // Local slash commands run before anything is sent to the model.
 319:     if (userInput.startsWith("/")) {
 320:       const result = await handleSlashCommand(userInput, makeCommandContext());
 321:       if (result.exit) break;
 322:       if (result.handled) continue;
 323:     }
 324: 
 325:     // Expand @file references into context attachments.
 326:     const { attachments, notes } = expandFileRefs(userInput, workspaceRoot);
 327:     for (const note of notes) console.log(chalk.gray(note));
 328: 
 329:     const contentText =
 330:       attachments.length > 0
 331:         ? `${userInput}\n\n${attachments.join("\n\n")}`
 332:         : userInput;
 333: 
 334:     // Add user message
 335:     messages.push({
 336:       role: "user",
 337:       content: [{ type: "text", text: contentText }],
 338:     });
 339: 
 340:     // Per-turn abort handling: first Ctrl+C aborts the current turn and
 341:     // returns to the prompt; a second (at the idle prompt) exits.
 342:     const controller = new AbortController();
 343:     const onSigint = () => {
 344:       controller.abort("用户中断");
 345:     };
 346:     process.on("SIGINT", onSigint);
 347: 
 348:     // Run agent loop
 349:     const loop = agentLoop(
 350:       messages,
 351:       tools,
 352:       callModel,
 353:       modelConfig,
 354:       {
 355:         systemPrompt,
 356:         maxTurns: 50,
 357:         toolContext: {
 358:           workspaceRoot,
 359:           sessionId: sessionId!,
 360:           permissionMode,
 361:           modelConfig,
 362:         },
 363:         askUser,
 364:         abortSignal: controller.signal,
 365:         hooks,
 366:       },
 367:     );
 368: 
 369:     let lastText = "";
 370:     let turnInputTokens = 0;
 371:     let turnOutputTokens = 0;
 372:     const renderer = new StreamingRenderer();
 373: 
 374:     for await (const event of loop) {
 375:       switch (event.type) {
 376:         case "text_delta":
 377:           renderer.write(event.delta);
 378:           lastText += event.delta;
 379:           break;
 380: 
 381:         case "tool_use":
 382:           renderer.flush();
 383:           renderToolStart(event.name, event.input);
 384:           break;
 385: 
 386:         case "tool_results":
 387:           renderer.flush();
 388:           for (const result of event.results) {
 389:             renderToolResult(result);
 390:           }
 391:           // Auto-save after tool execution
 392:           persistence.save(sessionId!, messages).catch(() => {});
 393:           break;
 394: 
 395:         case "compacting":
 396:           renderer.flush();
 397:           console.log("\n  📦 Compacting context...");
 398:           break;
 399: 
 400:         case "usage":
 401:           turnInputTokens += event.usage.input_tokens;
 402:           turnOutputTokens += event.usage.output_tokens;
 403:           break;
 404: 
 405:         case "error":
 406:           renderer.flush();
 407:           console.error(`\n  ⚠️ ${formatCliError(event.error)}`);
 408:           break;
 409: 
 410:         case "done":
 411:           renderer.flush();
 412:           if (uiState.showTokens && (turnInputTokens || turnOutputTokens)) {
 413:             console.log(
 414:               chalk.gray(
 415:                 `\n  [tokens: ${turnInputTokens} in / ${turnOutputTokens} out]`,
 416:               ),
 417:             );
 418:           }
 419:           // Final assistant text was added to messages in the loop
 420:           persistence.save(sessionId!, messages).catch(() => {});
 421:           break;
 422: 
 423:         case "aborted":
 424:           renderer.flush();
 425:           console.log(`\n  ⏹️ Aborted: ${event.reason}`);
 426:           break;
 427:       }
 428:     }
 429: 
 430:     // Detach this turn's SIGINT handler so handlers don't stack up.
 431:     process.removeListener("SIGINT", onSigint);
 432: 
 433:     console.log(""); // New line after response
 434:   }
 435: 
 436:   // Cleanup
 437:   rl.close();
 438:   await persistence.save(sessionId!, messages, { completed: true });
 439:   await mcpManager.disconnectAll();
 440:   console.log("\nGoodbye!");
 441: }
 442: 
 443: main().catch((error) => {
 444:   console.error("Fatal error:", formatCliError(error));
 445:   process.exit(1);
 446: });
