   1: // ============================================================
   2: // Core Types for Claude Code Replica
   3: // ============================================================
   4: 
   5: // --- Messages (Internal Format) ---
   6: 
   7: export type Message =
   8:   | UserMessage
   9:   | AssistantMessage
  10:   | ToolResultMessage
  11:   | SystemMessage;
  12: 
  13: export interface UserMessage {
  14:   role: "user";
  15:   content: ContentBlock[];
  16: }
  17: 
  18: export interface AssistantMessage {
  19:   role: "assistant";
  20:   content: string | null;
  21:   tool_calls?: ToolCall[];
  22: }
  23: 
  24: export interface ToolResultMessage {
  25:   role: "tool";
  26:   tool_call_id: string;
  27:   name?: string;
  28:   content: string;
  29: }
  30: 
  31: export interface SystemMessage {
  32:   role: "system";
  33:   content: string;
  34: }
  35: 
  36: // --- Content Blocks ---
  37: 
  38: export type ContentBlock = TextContent | ImageContent;
  39: 
  40: export interface TextContent {
  41:   type: "text";
  42:   text: string;
  43: }
  44: 
  45: export interface ImageContent {
  46:   type: "image";
  47:   source: {
  48:     type: "base64" | "url";
  49:     media_type: string;
  50:     data?: string;
  51:     url?: string;
  52:   };
  53: }
  54: 
  55: // --- Tool Calls ---
  56: 
  57: export interface ToolCall {
  58:   id: string;
  59:   type: "function";
  60:   function: {
  61:     name: string;
  62:     arguments: string; // JSON string
  63:   };
  64: }
  65: 
  66: // --- Tool System ---
  67: 
  68: export interface ToolInput {
  69:   [key: string]: unknown;
  70: }
  71: 
  72: export interface ToolResult {
  73:   content: string;
  74:   error?: string;
  75:   truncated?: boolean;
  76:   metadata?: ToolResultMetadata;
  77:   /**
  78:    * Optional image blocks produced by the tool (e.g. Read on a PNG/PDF).
  79:    * The agent loop injects these into the conversation as a follow-up user
  80:    * message, since both providers accept images only in user content.
  81:    */
  82:   images?: ImageContent[];
  83: }
  84: 
  85: export interface ToolResultMetadata {
  86:   durationMs?: number;
  87:   linesRead?: number;
  88:   fileSize?: number;
  89:   exitCode?: number;
  90: }
  91: 
  92: export interface ToolContext {
  93:   workspaceRoot: string;
  94:   sessionId: string;
  95:   permissionMode: PermissionMode;
  96:   /** Optional: model config for sub-agents (Task tool) */
  97:   modelConfig?: ModelConfig;
  98: }
  99: 
 100: export type PermissionMode =
 101:   | "default"
 102:   | "acceptEdits"
 103:   | "bypassPermissions"
 104:   | "plan";
 105: 
 106: export type PermissionResult =
 107:   | { allowed: true }
 108:   | { allowed: false; reason: string };
 109: 
 110: export interface Tool<T extends ToolInput = ToolInput> {
 111:   /** Unique tool name */
 112:   name: string;
 113:   /** Human-readable description */
 114:   description: string;
 115:   /** Description for the LLM system prompt */
 116:   promptDescription: string;
 117:   /** JSON Schema for input validation */
 118:   inputSchema: {
 119:     type: "object";
 120:     properties: Record<
 121:       string,
 122:       {
 123:         type: string;
 124:         description?: string;
 125:         enum?: string[];
 126:         default?: unknown;
 127:         /** For array properties: the schema of each item. */
 128:         items?: Record<string, unknown>;
 129:         [key: string]: unknown;
 130:       }
 131:     >;
 132:     required: string[];
 133:   };
 134:   /** Whether this tool is currently enabled */
 135:   isEnabled(): boolean;
 136:   /** Whether this tool only reads (auto-approved) */
 137:   isReadOnly(): boolean;
 138:   /** Whether this tool can run concurrently */
 139:   isConcurrencySafe(): boolean;
 140:   /** Main execution */
 141:   call(input: T, context: ToolContext): Promise<ToolResult>;
 142:   /** Permission check */
 143:   checkPermissions(
 144:     input: T,
 145:     context: ToolContext,
 146:   ): Promise<PermissionResult>;
 147:   /** Format result for LLM */
 148:   formatResult(result: ToolResult): string;
 149: }
 150: 
 151: // --- Model Config ---
 152: 
 153: export interface ModelConfig {
 154:   provider: "anthropic" | "openai" | "deepseek" | "qwen" | "moonshot" | "zhipu" | "custom";
 155:   model: string;
 156:   apiKey: string;
 157:   baseURL?: string;
 158:   maxTokens?: number;
 159:   temperature?: number;
 160:   options?: Record<string, unknown>;
 161: }
 162: 
 163: // --- Stream Events ---
 164: 
 165: export type StreamEvent =
 166:   | { type: "text_delta"; delta: string }
 167:   | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 168:   | { type: "thinking"; delta?: string }
 169:   | {
 170:       type: "done";
 171:       usage: { input_tokens: number; output_tokens: number };
 172:       finish_reason: string;
 173:     }
