   4: 
   5: import type { Tool, ToolInput, ToolContext, ToolResult, PermissionResult } from "./types.js";
   6: 
   7: export class ToolRegistry {
   8:   private tools: Map<string, Tool> = new Map();
   9: 
  10:   register(tool: Tool): void {
  11:     if (this.tools.has(tool.name)) {
  12:       throw new Error(`Tool "${tool.name}" is already registered`);
  13:     }
  14:     this.tools.set(tool.name, tool);
  15:   }
  16: 
  17:   unregister(name: string): void {
  18:     this.tools.delete(name);
  19:   }
  20: 
  21:   getEnabledTools(): Tool[] {
  22:     return Array.from(this.tools.values()).filter((t) => t.isEnabled());
  23:   }
  24: 
  25:   getTool(name: string): Tool | undefined {
  26:     return this.tools.get(name);
  27:   }
  28: 
  29:   /**
  30:    * Generate the "AVAILABLE TOOLS" section for system prompt
  31:    */
  32:   formatToolsForLLM(): string {
  33:     return this.getEnabledTools()
  34:       .map(
  35:         (t) =>
  36:           `${t.name} — ${t.promptDescription}\n  Parameters: ${JSON.stringify(t.inputSchema.properties)}`,
  37:       )
  38:       .join("\n\n");
  39:   }
  40: 
  41:   /**
  42:    * Convert to OpenAI function calling format
  43:    */
  44:   formatToolsForOpenAI(): Array<{
  45:     type: "function";
  46:     function: { name: string; description: string; parameters: object };
  47:   }> {
  48:     return this.getEnabledTools().map((t) => ({
  49:       type: "function" as const,
  50:       function: {
  51:         name: t.name,
  52:         description: t.promptDescription,
  53:         parameters: t.inputSchema,
  54:       },
  55:     }));
  56:   }
  57: 
  58:   /**
  59:    * Get the count of enabled tools
  60:    */
  61:   get enabledCount(): number {
  62:     return this.getEnabledTools().length;
  63:   }
  64: }
  65: 
  66: // ============================================================
  67: // Base Tool Implementation Helper
  68: // ============================================================
  69: 
  70: export interface BaseToolConfig<T extends ToolInput = ToolInput> {
  71:   name: string;
  72:   description: string;
  73:   promptDescription: string;
  74:   inputSchema: Tool["inputSchema"];
  75:   isReadOnly: boolean;
  76:   isConcurrencySafe: boolean;
  77:   call: (input: T, context: ToolContext) => Promise<ToolResult>;
  78:   formatResult?: (result: ToolResult) => string;
  79:   checkPermissions?: (
  80:     input: T,
  81:     context: ToolContext,
  82:   ) => Promise<PermissionResult>;
  83: }
  84: 
  85: export function createTool<T extends ToolInput = ToolInput>(
  86:   config: BaseToolConfig<T>,
  87: ): Tool<T> {
  88:   return {
  89:     name: config.name,
  90:     description: config.description,
  91:     promptDescription: config.promptDescription,
  92:     inputSchema: config.inputSchema,
  93:     isEnabled: () => true, // Can be overridden
  94:     isReadOnly: () => config.isReadOnly,
  95:     isConcurrencySafe: () => config.isConcurrencySafe,
  96:     call: config.call,
  97:     formatResult:
  98:       config.formatResult ??
  99:       ((result: ToolResult): string => {
 100:         if (result.error) {
 101:           return `Error: ${result.error}`;
 102:         }
 103:         const metadata = result.metadata
 104:           ? `\n[${result.metadata.durationMs ?? 0}ms]`
 105:           : "";
 106:         const truncated = result.truncated
 107:           ? "\n[... result too long, truncated]"
 108:           : "";
 109:         return result.content + metadata + truncated;
 110:       }),
 111:     checkPermissions: config.checkPermissions ??
 112:       (async (): Promise<PermissionResult> => ({ allowed: true })),
 113:   };
 114: }
