 215: /**
 216:  * Handle a line of input if it is a slash command.
 217:  * Returns handled=false for normal text so the caller sends it to the LLM.
 218:  */
 219: export async function handleSlashCommand(
 220:   input: string,
 221:   ctx: CommandContext,
 222: ): Promise<CommandResult> {
 223:   if (!input.startsWith("/")) return { handled: false };
 224: 
 225:   const [rawName, ...rest] = input.slice(1).split(/\s+/);
 226:   const name = rawName.toLowerCase();
 227:   const args = input.slice(1 + rawName.length).trim();
 228:   const cmd = COMMAND_MAP.get(name);
 229: 
 230:   if (!cmd) {
 231:     console.log(chalk.yellow(`  Unknown command: /${name}. Try /help.`));
 232:     return { handled: true };
 233:   }
 234: 
 235:   await cmd.run(args, ctx);
 236:   return { handled: true };
 237: }
