   1: // ============================================================
   2: // CLI input reader — readline wrapper with EOF-safe semantics
   3: // ============================================================
   4: // readline.question throws ERR_USE_AFTER_CLOSE if stdin has already closed
   5: // (piped input drained, Ctrl+D, etc.). It also behaves poorly for automated
   6: // multi-line pipes because the stream may close before the next question is
   7: // issued. This wrapper consumes readline's `line` events into a queue so both
   8: // real TTY input and `printf '...\n...' | node dist/cli.js` work reliably.
   9: // ============================================================
  10: 
  11: import type * as readline from "node:readline";
  12: 
  13: export interface CliInputReader {
  14:   askQuestion(prompt: string): Promise<string | null>;
  15:   readInput(): Promise<string | null>;
  16:   isClosed(): boolean;
  17: }
  18: 
  19: export function createCliInputReader(
  20:   rl: readline.Interface,
  21: ): CliInputReader {
  22:   let stdinClosed = false;
  23:   const queue: string[] = [];
  24:   const waiters: Array<(line: string | null) => void> = [];
  25: 
  26:   const flushWaiter = (line: string | null): void => {
  27:     const waiter = waiters.shift();
  28:     if (waiter) waiter(line);
  29:     else if (line !== null) queue.push(line);
  30:   };
  31: 
  32:   rl.on("line", (line) => flushWaiter(line));
  33:   rl.on("close", () => {
  34:     stdinClosed = true;
  35:     while (waiters.length > 0) {
  36:       waiters.shift()!(null);
  37:     }
  38:   });
  39: 
  40:   const askQuestion = (prompt: string): Promise<string | null> => {
  41:     if (prompt) process.stdout.write(prompt);
  42:     if (queue.length > 0) return Promise.resolve(queue.shift()!);
  43:     if (stdinClosed) return Promise.resolve(null);
  44:     return new Promise((resolve) => waiters.push(resolve));
  45:   };
  46: 
  47:   const readInput = async (): Promise<string | null> => {
  48:     const first0 = await askQuestion("\n> ");
  49:     if (first0 === null) return null;
  50:     let first = first0;
  51:     if (!first) return first;
  52: 
  53:     const lines: string[] = [];
  54:     let inFence = /^```/.test(first.trimStart());
  55: 
  56:     const continues = (line: string) => line.endsWith("\\");
  57:     let pendingContinuation = continues(first) && !inFence;
  58:     if (pendingContinuation) first = first.slice(0, -1);
  59:     lines.push(first);
  60: 
  61:     while (inFence || pendingContinuation) {
  62:       const next = await askQuestion(inFence ? "… " : "… ");
  63:       if (next === null) break;
  64:       if (inFence) {
  65:         lines.push(next);
  66:         if (/^```/.test(next.trimStart())) inFence = false;
  67:       } else {
  68:         pendingContinuation = continues(next);
  69:         lines.push(pendingContinuation ? next.slice(0, -1) : next);
  70:       }
  71:     }
  72: 
  73:     return lines.join("\n");
  74:   };
  75: 
  76:   return {
  77:     askQuestion,
  78:     readInput,
  79:     isClosed: () => stdinClosed,
  80:   };
  81: }
